import{_ as e,c as t,o,a2 as d}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"FormBaseField","description":"","frontmatter":{"sidebarPos":7,"sidebarTitle":"Form Base Field"},"headers":[],"relativePath":"guide/components/others/form-base-field.md","filePath":"guide/components/others/form-base-field.md","lastUpdated":1777448653000}'),c={name:"guide/components/others/form-base-field.md"},r=d('<h1 id="formbasefield" tabindex="-1">FormBaseField <a class="header-anchor" href="#formbasefield" aria-label="Permalink to &quot;FormBaseField&quot;">​</a></h1><p><code>FormBaseField</code> is the internal field-renderer sub-component of <a href="./form-base"><code>FormBase</code></a>. It receives a single schema field descriptor (<code>obj</code>) and a <code>ctx</code> handle to the parent&#39;s <code>useFormBaseLogic</code> composable, then selects and renders the appropriate Vuetify or custom component.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This is an internal component of <code>FormBase</code>. You do not use it directly. Customise output through <code>FormBase</code> slots.</p></div><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>obj</code></td><td><code>Object</code></td><td>Yes</td><td>Field descriptor <code>{ key, value, schema }</code> from the flattened combined array</td></tr><tr><td><code>ctx</code></td><td><code>Object</code></td><td>Yes</td><td>The <code>useFormBaseLogic</code> composable context returned from <code>FormBase.setup</code></td></tr><tr><td><code>index</code></td><td><code>Number</code></td><td>Yes</td><td>Field position in the sorted array</td></tr><tr><td><code>formItem</code></td><td><code>Object</code></td><td>No</td><td>Forwarded to <code>preview</code> type fields via <code>ue-recursive-stuff</code></td></tr></tbody></table><h2 id="rendering-decision-tree" tabindex="-1">Rendering decision tree <a class="header-anchor" href="#rendering-decision-tree" aria-label="Permalink to &quot;Rendering decision tree&quot;">​</a></h2><p>Fields are matched in priority order:</p><table><thead><tr><th>Condition</th><th>Rendered as</th></tr></thead><tbody><tr><td><code>type === &#39;preview&#39;</code> and <code>schema.configuration</code> set</td><td><code>ue-recursive-stuff</code></td></tr><tr><td><code>type === &#39;dynamic-component&#39;</code></td><td><code>ue-dynamic-component-renderer</code></td></tr><tr><td><code>type === &#39;title&#39;</code></td><td>Mapped component via registry</td></tr><tr><td><code>type === &#39;radio&#39;</code></td><td>Mapped component with <code>options</code> and inject slots</td></tr><tr><td><code>isDateTimeColorTypeAndExtensionText(obj)</code></td><td><code>v-menu</code> wrapping a <code>v-text-field</code> activator + a date/time/color picker</td></tr><tr><td><code>type === &#39;array&#39;</code></td><td><code>div</code> loop + nested <code>v-form-base</code> per item</td></tr><tr><td><code>type === &#39;group&#39;</code> or <code>&#39;wrap&#39;</code></td><td>Container component (default <code>v-card</code>) + nested <code>v-form-base</code></td></tr><tr><td><code>type === &#39;treeview&#39;</code></td><td><code>VTreeview</code> (from <code>vuetify/labs/VTreeview</code>)</td></tr><tr><td><code>type === &#39;list&#39;</code></td><td><code>v-list</code> with optional toolbar label</td></tr><tr><td><code>type === &#39;checkbox&#39;</code> or <code>&#39;switch&#39;</code></td><td>Mapped component</td></tr><tr><td><code>type === &#39;file&#39;</code></td><td><code>v-file-input</code></td></tr><tr><td><code>type === &#39;icon&#39;</code></td><td><code>v-icon</code></td></tr><tr><td><code>type === &#39;slider&#39;</code></td><td><code>v-slider</code></td></tr><tr><td><code>type === &#39;img&#39;</code></td><td><code>v-img</code></td></tr><tr><td><code>type === &#39;btn-toggle&#39;</code></td><td><code>v-btn-toggle</code> with option buttons</td></tr><tr><td><code>type === &#39;btn&#39;</code></td><td><code>v-btn</code></td></tr><tr><td><code>schema.translated</code> is set</td><td><code>v-input-locale</code></td></tr><tr><td><code>schema.mask</code> is set</td><td>Mapped component with <code>v-mask</code> directive</td></tr><tr><td>Default</td><td>Mapped component via registry</td></tr></tbody></table><h2 id="type-mapping" tabindex="-1">Type mapping <a class="header-anchor" href="#type-mapping" aria-label="Permalink to &quot;Type mapping&quot;">​</a></h2><p><code>ctx.mapTypeToComponent(type)</code> resolves a schema type string to a Vue component using the global input registry. Custom types registered via <code>registerInputType</code> are also resolved here.</p><h2 id="group-wrap-containers" tabindex="-1">Group / Wrap containers <a class="header-anchor" href="#group-wrap-containers" aria-label="Permalink to &quot;Group / Wrap containers&quot;">​</a></h2><p>For <code>group</code> and <code>wrap</code> types, the wrapping component is resolved via <code>ctx.checkInternGroupType(obj)</code>:</p><ul><li>Uses <code>obj.schema.typeInt</code> if set.</li><li>Falls back to <code>v-card</code>.</li><li>Accepts any <code>v-*</code> or <code>ue-*</code> prefixed component name.</li></ul><p>Optional <code>title</code> and <code>subtitle</code> strings are rendered above the nested form using <code>ue-title</code>.</p><h2 id="slot-passthrough" tabindex="-1">Slot passthrough <a class="header-anchor" href="#slot-passthrough" aria-label="Permalink to &quot;Slot passthrough&quot;">​</a></h2><p><code>FormBaseField</code> passes all of <code>$slots</code> into nested <code>v-form-base</code> instances (for <code>array</code> and <code>group</code>/<code>wrap</code> types), and into each rendered component via <code>getInjectedScopedSlots</code> / <code>getKeyInjectSlot</code> for inject slots. This is how parent <code>FormBase</code> slots reach deeply nested fields.</p>',16),a=[r];function s(i,n,p,l,h,m){return o(),t("div",null,a)}const f=e(c,[["render",s]]);export{b as __pageData,f as default};
